select run_time::date d, job_name, count(*) n, count(*) filter (where status='success') ok, count(*) filter (where status='failure') fail, count(*) filter (where status='continued') cont, string_agg(distinct left(((details->>'response')::jsonb->'failureSummary'->'terminalStop'->>'code')||':'||((details->>'response')::jsonb->'failureSummary'->'terminalStop'->>'stageId'),60),' | ') stop from cron_job_audit where run_time >= '2026-11-01' and run_time < '2026-11-09' and job_name in ('run-rolling-forge-pipeline') group by 1,2 order by 1
